    /// <summary>The <c>batch</c> entry of <c>pangloss --describe</c> from v0.33.0, which has no <c>--morph-spans</c>; the other commands are left out.</summary>
    public const string DescribeBatchV033 = @"{""commands"":[{""name"":""batch"",""summary"":""Parse every word in a word list against a grammar and write a batch TSV."",""hidden"":false,""positionals"":[""grammar"",""words.txt"",""out.tsv""],""flags"":[{""name"":""--trace-rejections"",""takes_value"":true,""summary"":""write a bounded rejection diagnostic JSONL artifact""},{""name"":""--trace-options"",""takes_value"":true,""summary"":""versioned rejection trace request metadata""},{""name"":""--trace-max-paths"",""takes_value"":true,""summary"":""maximum retained witnesses per row (default 16)""},{""name"":""--trace-max-depth"",""takes_value"":true,""summary"":""maximum retained lineage edges per witness (default 32)""},{""name"":""--trace-max-events"",""takes_value"":true,""summary"":""maximum retained events per row (default 128)""},{""name"":""--engine"",""takes_value"":true,""summary"":""hc|fst (default hc); adds JSON completion metadata; fst needs foma-tools, --threads 1, --work-cap unbounded, --word-mem-cap-mib 0 and --capture-cap-mib unbounded; no fallback; FST has no per-word deadline or process RSS bound: use an external watchdog with a deadline and memory ceiling""},{""name"":""--word-mem-cap-mib"",""takes_value"":true,""summary"":""counted MiB of retained per-word parser state (default 100; 0 unbounded); writes MEMCAP when reached""},{""name"":""--work-cap"",""takes_value"":true,""summary"":""N or \""unbounded\""; the work steps one word may spend in analysis (default: 5000000000); confirmation may spend one sixteenth more""},{""name"":""--capture-cap-mib"",""takes_value"":true,""summary"":""N or \""unbounded\""; MiB of affix-matching capture state one word may hold at once (default: 256); a word that reaches it writes a MEMCAP row""},{""name"":""--word-timeout-ms"",""takes_value"":true,""summary"":""wall-clock deadline per word, independent of --work-cap""},{""name"":""--threads"",""takes_value"":true,""summary"":""thread count; 1 keeps the crash-resumable sequential writer""},{""name"":""--start"",""takes_value"":true,""summary"":""0-based resume index; skips already-completed words and appends to <out.tsv>""},{""name"":""--analyses"",""takes_value"":true,""summary"":""write FieldWorks ParseAnalysis JSONL rows to this sidecar path""},{""name"":""--guess"",""takes_value"":false,""summary"":""retry an out-of-lexicon empty analysis via the lexical-pattern guesser; =false turns it off; overrides the project's <HC><GuessRoots> (default true), which applies when the flag is absent""},{""name"":""--partials"",""takes_value"":true,""summary"":""append up to K same-pass rejection summaries as JSON (K=1..3); requires --prefilter off""},{""name"":""--work-columns"",""takes_value"":false,""summary"":""append each word's work_steps (its deterministic work) to its TSV row""},{""name"":""--cost-column"",""takes_value"":false,""summary"":""append each word's work_steps and then its fixed-weight parse cost, the last field; compare two runs with cost-compare""},{""name"":""--no-flush"",""takes_value"":false,""summary"":""with --threads 1, keep rows buffered instead of flushing after each word; same file at exit, no crash-resume; for instruction counting""},{""name"":""--phase-marks"",""takes_value"":false,""summary"":""with --threads 1, start and join a spinning thread before the first word and after the last, so a PMC trace can count the parse apart from the grammar load; for instruction-compare""},{""name"":""--stats"",""takes_value"":false,""summary"":""record batch statistics in the stats cache (full profile by default)""},{""name"":""--stats-profile"",""takes_value"":true,""summary"":""full|word-only (requires --stats); word-only records per-word timing, work and outcomes, omitting object, gate and prune counters""},{""name"":""--cache-pack"",""takes_value"":false,""summary"":""compress facts at rest, leaving word rows directly readable (requires full stats)""},{""name"":""--stats-compact"",""takes_value"":false,""summary"":""retain object totals without allomorph/stratum dimensions (requires full stats)""},{""name"":""--cache"",""takes_value"":true,""summary"":""stats cache path override (with --stats)""},{""name"":""--stats-manifest"",""takes_value"":true,""summary"":""publish a frozen stats-run manifest after the stats cache commits""},{""name"":""--always-enforce-final-templates"",""takes_value"":false,""summary"":""enforce template order even where partial-rule rescue would allow interleaving; =false turns it off; overrides the project's <HC><MakePartialsFinal>, which applies when the flag is absent""},{""name"":""--prefilter"",""takes_value"":true,""summary"":""auto|on|off (default off); on is a verification and measurement mode: no warm-up, calibration, budget or minimum batch length, every stage that is valid for the grammar runs on every word (a stage that is not valid is off with its reason) and the whole construction is paid whatever the batch length; auto lets a load-time calibration decide whether a rule-admission filter and a tiled whole-word test, built from the grammar, narrow each word's parse; needs the foma-tools build feature (auto and on); refused with --stats and --word-timeout-ms; --work-columns and --cost-column give the work the selected pipeline spent; prints PREFILTER and PREFILTER-TOTAL lines on stderr; the gate prices parses in full parser work (auto and on turn the cost meter on, with or without --cost-column, so the decision line is the same either way; auto turns it off again after the calibration unless --cost-column is given); analyses equal off on every word whose parse completes in both modes, and a word that is incomplete in either mode (work cap, capture cap) can have a different partial list; batches under 512 words stay plain""}]}]}";

